
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_lag_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_lag", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.178388011067285e+00, -4.094769592386891e+00, -3.977622300077638e+00, -3.815393762077706e+00, -3.594450831504058e+00, -3.300668494268093e+00, -2.923255624607975e+00, -2.461917133430390e+00, -1.937748010870093e+00, -1.404776932066187e+00, -9.435475925411999e-01, -6.778421222450850e-01, -5.905691466714008e-01, -4.761018607983709e-01, -3.337295004693144e-01, -2.064554151656261e-01, -1.219276144260302e-01, -6.957538504604409e-02, -4.120231781718251e-02, -2.830304771694548e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


